query:
query ReviewThreads {
  repository(owner: "adm01-debug", name: "Fast_Gravacoes_V2") {
    pullRequest(number: 256) {
      reviewThreads(first: 20) {
        nodes {
          id
          isResolved
          comments(first: 8) {
            nodes {
              id
              author { login }
            }
          }
        }
      }
    }
  }
}
